class Solution:
    def lastNonEmptyString(self, s: str) -> str:
        positions = {chr(ord('a')+i): [] for i in range(26)}
        idx = {chr(ord('a')+i): 0 for i in range(26)}
        removal_time = [0]*len(s)
        n = len(s)
        for i, c in enumerate(s):
            positions[c].append(i)
        t = 1
        total_removed = 0
        while total_removed < n:
            for c in map(chr, range(ord('a'), ord('z')+1)):
                if idx[c] < len(positions[c]):
                    pos = positions[c][idx[c]]
                    removal_time[pos] = t
                    idx[c] += 1
                    total_removed += 1
            t += 1
        t_max = t - 1
        last_positions = [i for i in range(len(s)) if removal_time[i] >= t_max]
        last_positions.sort()
        result = ''.join(s[i] for i in last_positions)
        return result
