    def isPossibleToSplit(self, nums: List[int]) -> bool:
        from collections import Counter

        counts = Counter(nums)
        k = len(nums) // 2
        nums1 = set()
        nums2 = set()

        # Sort elements by counts descending
        elements = sorted(counts.keys(), key=lambda x: -counts[x])

        for e in elements:
            c = counts[e]
            added_to_nums1 = False
            added_to_nums2 = False

            if len(nums1) < k and e not in nums1:
                nums1.add(e)
                counts[e] -=1
                added_to_nums1 = True

            if len(nums2) < k and counts[e]>0 and e not in nums2:
                nums2.add(e)
                counts[e] -=1
                added_to_nums2 = True

            # Try to add remaining counts of e to nums1 and nums2
            while counts[e] > 0 and (len(nums1) < k or len(nums2) < k):
                if len(nums1) < k and e not in nums1:
                    nums1.add(e)
                    counts[e] -=1
                elif len(nums2) < k and e not in nums2:
                    nums2.add(e)
                    counts[e] -=1
                else:
                    break

        # Try to fill in nums1 and nums2 with remaining elements
        for e in elements:
            while counts[e] > 0 and (len(nums1) < k or len(nums2) < k):
                if len(nums1) < k and e not in nums1:
                    nums1.add(e)
                    counts[e] -=1
                elif len(nums2) < k and e not in nums2:
                    nums2.add(e)
                    counts[e] -=1
                else:
                    break

        return len(nums1) == k and len(nums2) == k
